@Composable private fun AuditTab(repo:Repository){var rows by remember{mutableStateOf(emptyList<JsonObject>())};var error by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();fun load(){scope.launch{runCatching{repo.logs()}.onSuccess{rows=it.a("items")}.onFailure{error=it.message}}};LaunchedEffect(Unit){load()};Column{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Audit Log",style=MaterialTheme.typography.titleLarge);Button(::load){Text("Refresh")}};error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(rows){r->Text("${r.s("created_at","timestamp")} · ${r.s("action")} · ${r.s("table_name","table")} · ${r.s("user_nama","username")}",Modifier.padding(5.dp));Text("before=${r.s("data_before")} after=${r.s("data_after")}",Modifier.padding(start=10.dp))}}}}
@Composable private fun NotifHookTab(repo:Repository){var key by remember{mutableStateOf("")};var payload by remember{mutableStateOf("")};var result by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();Column(verticalArrangement=Arrangement.spacedBy(6.dp)){Text("NotifHook",style=MaterialTheme.typography.titleLarge);NativeTextField(key,{key=it},"X-API-Key");NativeTextField(payload,{payload=it},"Payload JSON");Button({scope.launch{runCatching{repo.notifhook(Json.parseToJsonElement(payload).jsonObject,key)}.onSuccess{result="Webhook berhasil diterima"}.onFailure{result=it.message}}}){Text("Kirim webhook")};result?.let{Text(it)}}}
